from typing import List

def getWinner(arr: List[int], k: int) -> int:
    max_elem = arr[0]
    cnt = 0
    for x in arr[1:]:
        if x > max_elem:
            max_elem = x
            cnt = 1
        else:
            cnt += 1
        if cnt == k:
            return max_elem
    return max_elem
